#!/usr/bin/env bash
# ============================================================
#  Bedrock Bot Manager — универсальный установщик (один файл)
# ============================================================

set -e

INSTALLER_VERSION="1.8.1"
INSTALLER_FEATURES="tabs,pinger,auto-connect,bulk-actions,termux-notify,inst-json,cluster,install-mode,port-picker,colored-ui,ip-required-bore"

# ---------- Цвета для красивого интерфейса (ANSI, поддерживаются терминалом Termux) ----------
C_RESET='\033[0m'
C_BOLD='\033[1m'
C_DIM='\033[2m'
C_ACCENT='\033[38;5;114m'   # мягкий зелёный — выбранный пункт
C_CYAN='\033[38;5;110m'     # заголовки
C_WARN='\033[38;5;179m'     # предупреждения/акценты

# Простое меню выбора стрелками (↑/↓ + Enter). Возвращает индекс выбранного пункта через echo.
# ВАЖНО: весь визуальный вывод идёт в stderr (>&2), чтобы не потеряться при
# вызове через command substitution — вида `x=$(arrow_select ...)`.
arrow_select() {
  local prompt="$1"; shift
  local opts=("$@")
  local sel=0
  local key rest

  while true; do
    clear >&2
    printf "${C_CYAN}${C_BOLD}%s${C_RESET}\n\n" "$prompt" >&2
    for i in "${!opts[@]}"; do
      if [ "$i" -eq "$sel" ]; then
        printf "  ${C_ACCENT}${C_BOLD}➤ %s${C_RESET}\n" "${opts[$i]}" >&2
      else
        printf "    ${C_DIM}%s${C_RESET}\n" "${opts[$i]}" >&2
      fi
    done
    printf "\n${C_DIM}(↑/↓ — выбор, Enter — подтвердить)${C_RESET}\n" >&2

    IFS= read -rsn1 key
    if [[ "$key" == $'\x1b' ]]; then
      IFS= read -rsn2 -t 0.2 rest
      case "$rest" in
        '[A') sel=$(( (sel - 1 + ${#opts[@]}) % ${#opts[@]} )) ;;
        '[B') sel=$(( (sel + 1) % ${#opts[@]} )) ;;
      esac
    elif [[ -z "$key" ]]; then
      break
    fi
  done
  echo "$sel"
}

# Да/Нет тоже через стрелки, для единого стиля интерфейса.
ask_yn() {
  local prompt="$1"
  local idx
  idx=$(arrow_select "$prompt" "Да" "Нет")
  [ "$idx" = "0" ]
}

# Проверяет, что node реально запускается (а не падает с CANNOT LINK EXECUTABLE
# из-за рассинхрона с openssl), и чинит его переустановкой при необходимости.
# Проблема часто всплывает не только до установки, но и ПОСЛЕ pkg install/upgrade,
# когда обновляется openssl, а nodejs остаётся собран под старую версию.
fix_node_if_broken() {
  if ! command -v node >/dev/null 2>&1; then
    return 0
  fi
  if node --version >/dev/null 2>&1; then
    return 0
  fi
  echo "[!] Node.js повреждён (рассинхрон с openssl после обновления)."
  echo "[i] Переустанавливаем nodejs и openssl..."
  pkg update -y
  pkg install -y -o Dpkg::Options::=--force-confnew openssl
  pkg reinstall -y -o Dpkg::Options::=--force-confnew nodejs openssl
  if ! node --version >/dev/null 2>&1; then
    echo "[✗] Не получилось починить Node.js автоматически."
    echo "    Попробуй вручную: pkg reinstall nodejs openssl"
    exit 1
  fi
  echo "[✓] Node.js починен: $(node --version)"
}

clear
echo "============================================="
echo " Bedrock Bot Manager — установка"
echo "============================================="
echo

# ---------- Проверка целостности Node.js (частая проблема Termux) ----------
fix_node_if_broken
echo

# ---------- Выбор режима установки ----------
mode_idx=$(arrow_select "Что установить на это устройство?" \
  "Сервер для ботов — хостит ботов, БЕЗ веб-панели (управляется удалённо)" \
  "Клиент-панель — только веб-панель, БЕЗ хостинга ботов на этом устройстве")

if [ "$mode_idx" = "1" ]; then
  INSTALL_MODE="client"
else
  INSTALL_MODE="server"
fi

clear
if [ "$INSTALL_MODE" = "client" ]; then
  printf "${C_CYAN}${C_BOLD}=============================================${C_RESET}\n"
  printf "${C_CYAN}${C_BOLD} Режим: Клиент-панель${C_RESET}\n"
  printf "${C_CYAN}${C_BOLD}=============================================${C_RESET}\n"
  echo "Боты здесь ставиться и работать НЕ будут — своей веб-страницы для"
  echo "управления у сервера нет, весь просмотр и управление идёт отсюда."
  echo "Добавишь адреса серверов во вкладке «Серверы» после установки."
else
  printf "${C_CYAN}${C_BOLD}=============================================${C_RESET}\n"
  printf "${C_CYAN}${C_BOLD} Режим: Сервер для ботов${C_RESET}\n"
  printf "${C_CYAN}${C_BOLD}=============================================${C_RESET}\n"
  echo "Боты будут ставиться и работать прямо на этом устройстве, но"
  echo "своей веб-панели у него не будет — управляй им с клиент-панели,"
  echo "добавив адрес этого сервера в её вкладке «Серверы»."
fi
echo

if [ -d "$HOME/storage/shared" ]; then
  echo "[i] Доступ к памяти телефона уже настроен, пропускаю запрос."
elif [ -d "$HOME/storage" ]; then
  echo "[i] Папка ~/storage уже существует, но ~/storage/shared не найдена —"
  echo "    похоже, разрешение раньше не было выдано. Не трогаю папку ~/storage"
  echo "    (иначе Termux спросит y/n о пересборке структуры) — просто запусти"
  echo "    вручную: termux-setup-storage, если нужен доступ к памяти телефона."
elif command -v termux-setup-storage >/dev/null 2>&1; then
  if ask_yn "Дать доступ к памяти телефона? (нужно для сохранения ботов, логов, поиска SD-карты)"; then
    termux-setup-storage
    echo
    echo "[!] Сейчас должен появиться системный диалог Android с запросом разрешения."
    echo "    Нажми там \"Разрешить\", а потом вернись сюда и нажми любую клавишу."
    read -rsn1
    echo "[i] Доступ к памяти запрошен."
  else
    echo "[i] Пропущено — установка будет только во внутреннюю память Termux."
  fi
else
  echo "[i] termux-setup-storage не найден (не Termux?), пропускаем."
fi
echo

if command -v am >/dev/null 2>&1; then
  if ask_yn "Открыть настройки Termux, чтобы включить полный доступ к файлам (\"Все файлы\") — без этого SD-карта может быть не видна?"; then
    am start -a android.settings.MANAGE_APP_ALL_FILES_ACCESS_PERMISSION -d package:com.termux >/dev/null 2>&1 || am start -a android.settings.APPLICATION_DETAILS_SETTINGS -d package:com.termux >/dev/null 2>&1 || true
    echo
    echo "[!] Должен открыться переключатель \"Доступ до всіх файлів\" для Termux."
    echo "    Включи его, потом вернись в Termux и нажми любую клавишу."
    echo "    (Если открылся общий список приложений — найди там Termux вручную.)"
    read -rsn1
  else
    echo "[i] Пропущено — если SD-карта не найдётся ниже, можно включить это позже вручную."
  fi
else
  echo "[i] Команда 'am' недоступна, пропускаем открытие настроек."
fi
echo

if command -v termux-wake-lock >/dev/null 2>&1; then
  if ask_yn "Разрешить фоновую работу без сна (wake-lock), чтобы боты не отваливались с выключенным экраном?"; then
    termux-wake-lock
    echo "[i] Фоновая работа включена (termux-wake-lock)."
  else
    echo "[i] Пропущено — при выключенном экране Android может остановить ботов."
  fi
else
  echo "[i] termux-wake-lock не найден, пропускаем."
fi
echo

INSTALL_SYS_DEPS=1
if command -v pkg >/dev/null 2>&1; then
  if [ "$INSTALL_MODE" = "client" ]; then
    sysdeps_prompt="Установить системные пакеты (nodejs, git) — нужны для работы панели?"
  else
    sysdeps_prompt="Установить системные пакеты (nodejs, git, cmake, clang, make, python) — нужны для работы и сборки ботов?"
  fi
  if ask_yn "$sysdeps_prompt"; then
    INSTALL_SYS_DEPS=1
  else
    INSTALL_SYS_DEPS=0
    echo "[i] Пропущено. Если Node.js/компилятор уже стоят — всё ок, установка продолжится."
  fi
fi
echo

SHARED_PATH=""
if [ -d "$HOME/storage/shared" ]; then
  SHARED_PATH="$HOME/storage/shared"
elif [ -d "$HOME/storage" ]; then
  echo "[!] Папка ~/storage есть, но ~/storage/shared не найдена."
  echo "    Похоже, доступ к памяти телефона не был предоставлен раньше."
  echo "    Выполни в Termux: termux-setup-storage — и запусти установщик заново."
fi

SDCARD_PATH=""
for candidate in "$HOME/storage/external-1" "$HOME/storage/sdcard1"; do
  if [ -d "$candidate" ] && [ -n "$(ls -A "$candidate" 2>/dev/null)" ]; then
    SDCARD_PATH="$candidate"
    break
  fi
done
if [ -z "$SDCARD_PATH" ] && [ -d /storage ]; then
  for d in /storage/*/; do
    base="$(basename "$d")"
    if [ "$base" != "emulated" ] && [ "$base" != "self" ] && [ -d "$d" ] && [ -n "$(ls -A "$d" 2>/dev/null)" ]; then
      SDCARD_PATH="${d%/}"
      break
    fi
  done
fi
if [ -n "$SHARED_PATH" ]; then
  echo "[i] Найдена внутренняя память телефона: $SHARED_PATH"
fi
if [ -n "$SDCARD_PATH" ]; then
  echo "[i] Найдена SD-карта: $SDCARD_PATH"
elif [ -z "$SHARED_PATH" ]; then
  echo "[i] Ни внутренняя память, ни SD-карта не найдены. Проверь, что оба разрешения выше приняты."
fi
echo
echo "Нажми любую клавишу, чтобы перейти к выбору папки установки..."
read -rsn1

pick_directory() {
  local current="$HOME"
  local selected=0
  local key key2 entries choice

  while true; do
    entries=("[ВЫБРАТЬ ЭТУ ПАПКУ]" "[ВВЕСТИ ПУТЬ ВРУЧНУЮ]")
    if [ -n "$SHARED_PATH" ] && [ "$current" != "$SHARED_PATH" ]; then
      entries+=("[ВНУТРЕННЯЯ ПАМЯТЬ ТЕЛЕФОНА]")
    fi
    if [ -n "$SDCARD_PATH" ] && [ "$current" != "$SDCARD_PATH" ]; then
      entries+=("[ПЕРЕЙТИ НА SD-КАРТУ]")
    fi
    if [ "$current" != "/" ]; then
      entries+=("..")
    fi
    while IFS= read -r d; do
      [ -n "$d" ] && entries+=("$(basename "$d")/")
    done < <(find "$current" -maxdepth 1 -mindepth 1 -type d 2>/dev/null | sort)

    {
      clear
      echo "=== Выбор папки установки ==="
      echo "Текущий путь: $current"
      echo "(стрелки вверх/вниз — навигация, Enter — выбрать)"
      echo
      for i in "${!entries[@]}"; do
        if [ "$i" -eq "$selected" ]; then
          echo " > ${entries[$i]}"
        else
          echo "   ${entries[$i]}"
        fi
      done
    } >&2

    IFS= read -rsn1 key
    if [[ "$key" == $'\x1b' ]]; then
      read -rsn2 key2
      key="$key$key2"
    fi

    case "$key" in
      $'\x1b[A')
        selected=$(( (selected - 1 + ${#entries[@]}) % ${#entries[@]} ))
        ;;
      $'\x1b[B')
        selected=$(( (selected + 1) % ${#entries[@]} ))
        ;;
      "")
        choice="${entries[$selected]}"
        if [ "$choice" == "[ВЫБРАТЬ ЭТУ ПАПКУ]" ]; then
          echo "$current"
          return 0
        elif [ "$choice" == "[ВВЕСТИ ПУТЬ ВРУЧНУЮ]" ]; then
          local custom
          read -rp "Введи путь: " custom >&2
          if [ -d "$custom" ]; then
            echo "$custom"
            return 0
          else
            echo "[!] Такой папки нет, нажми любую клавишу" >&2
            read -rsn1
          fi
        elif [ "$choice" == "[ВНУТРЕННЯЯ ПАМЯТЬ ТЕЛЕФОНА]" ]; then
          current="$SHARED_PATH"
          selected=0
        elif [ "$choice" == "[ПЕРЕЙТИ НА SD-КАРТУ]" ]; then
          current="$SDCARD_PATH"
          selected=0
        elif [ "$choice" == ".." ]; then
          current="$(dirname "$current")"
          selected=0
        else
          current="$current/${choice%/}"
          selected=0
        fi
        ;;
    esac
  done
}

TARGET_PARENT="$(pick_directory)"
TARGET="$TARGET_PARENT/bedrock-bots"

REINSTALL=1
ALREADY_INSTALLED=0
INSTALLED_VERSION=""
if [ -f "$TARGET/manager.js" ] && [ -f "$TARGET/package.json" ]; then
  ALREADY_INSTALLED=1
  if [ -f "$TARGET/inst.json" ]; then
    INSTALLED_VERSION="$(grep -o '"version"[[:space:]]*:[[:space:]]*"[^"]*"' "$TARGET/inst.json" | sed -E 's/.*"([0-9][^"]*)"/\1/')"
  fi
fi

clear
if [ "$ALREADY_INSTALLED" = "1" ]; then
  echo "============================================="
  echo " Уже установлено"
  echo "============================================="
  echo "Обнаружена существующая установка в: $TARGET"
  if [ -n "$INSTALLED_VERSION" ]; then
    if [ "$INSTALLED_VERSION" = "$INSTALLER_VERSION" ]; then
      echo "Версия: $INSTALLED_VERSION (совпадает с этим установщиком)"
    else
      echo "Установлена версия: $INSTALLED_VERSION  →  версия этого установщика: $INSTALLER_VERSION"
    fi
  else
    echo "Версия не определена (старая установка без inst.json)."
  fi
  echo "Боты и их логи (папка bots/, bots.json) при переустановке НЕ удаляются —"
  echo "перезаписываются только файлы самой панели (manager.js, public/, template/)."
  echo
  if ask_yn "Переустановить систему заново?"; then
    REINSTALL=1
  else
    REINSTALL=0
  fi
  echo
else
  echo "=== Установка в: $TARGET ==="
  echo
fi

if [ "$REINSTALL" = "1" ]; then

echo "[1/5] Создаём папки..."
if [ "$INSTALL_MODE" = "client" ]; then
  mkdir -p "$TARGET/public"
else
  mkdir -p "$TARGET/template" "$TARGET/bots"
fi
echo "      готово."
echo

if [ "$INSTALL_SYS_DEPS" = "1" ] && command -v pkg >/dev/null 2>&1; then
  if [ "$INSTALL_MODE" = "client" ]; then
    echo "[2/5] Обновляем pkg и ставим системные зависимости (nodejs, git)..."
    echo "      Клиент-режим — компилятор (cmake/clang/make/python) не нужен, боты тут не ставятся."
    pkg update -y
    pkg install -y nodejs git
  else
    echo "[2/5] Обновляем pkg и ставим системные зависимости (nodejs, git, cmake, clang, make, python)..."
    echo "      Это может занять пару минут, вывод pkg будет виден ниже."
    pkg update -y
    pkg install -y nodejs git cmake clang make python
  fi
  echo "      готово."
  # pkg install/upgrade мог подтянуть новый openssl без пересборки nodejs —
  # именно тут чаще всего вылезает CANNOT LINK EXECUTABLE ... OSSL_PROVIDER_add_conf_parameter.
  fix_node_if_broken
else
  echo "[2/5] Системные пакеты пропущены."
fi
echo

echo "[3/5] Создаём файлы проекта..."
echo "" | base64 -d > "$TARGET/manager.js"
echo "      manager.js"
if [ "$INSTALL_MODE" = "client" ]; then
  echo "" | base64 -d > "$TARGET/public/index.html"
fi
echo "      public/index.html"
if [ "$INSTALL_MODE" = "server" ]; then
  echo "ewogICJuYW1lIjogImJlZHJvY2stYm90LWluc3RhbmNlIiwKICAidmVyc2lvbiI6ICIxLjAuMCIsCiAgInByaXZhdGUiOiB0cnVlLAogICJkZXBlbmRlbmNpZXMiOiB7CiAgICAiYmVkcm9jay1wcm90b2NvbCI6ICJeMy4wLjAiCiAgfSwKICAib3ZlcnJpZGVzIjogewogICAgIm5vZGUtYWRkb24tYXBpIjogIl44LjAuMCIKICB9Cn0K" | base64 -d > "$TARGET/template/package.json"
echo "      template/package.json"
  echo "" | base64 -d > "$TARGET/template/bot-worker.js"
fi
echo "      template/bot-worker.js"
echo "" | base64 -d > "$TARGET/README.md"
echo "      README.md"
echo "      готово."
echo

if [ "$INSTALL_MODE" = "client" ]; then
  LAUNCHER_NAME="start-web-panel.sh"
else
  LAUNCHER_NAME="start-server-api"
fi

echo "[4/5] Создаём ярлык запуска (~/$LAUNCHER_NAME)..."
cat > "$TARGET/$LAUNCHER_NAME" << INNEREOF
#!/usr/bin/env bash
cd "\$(dirname "\${BASH_SOURCE[0]}")"

RESTART_LOG="supervisor.log"
MAX_FAST_RESTARTS=5
fast_restart_count=0
INSTALL_MODE="$INSTALL_MODE"

# ---------- Wake-lock: включаем автоматически при КАЖДОМ запуске лаунчера ----------
# Раньше это спрашивалось только один раз при установке (setup.sh) — если Termux
# перезапускался, телефон перезагружался или лок слетал вручную, при следующем
# запуске ~/$LAUNCHER_NAME он сам не включался. Теперь включаем без вопросов
# при каждом старте (снять можно командой termux-wake-unlock, если не нужно).
if command -v termux-wake-lock >/dev/null 2>&1; then
  termux-wake-lock
  echo "[i] Wake-lock включён — экран может гаснуть, процесс не заснёт."
fi

# Сбрасываем всё, что могло застрять во входном буфере (например, случайный Enter,
# нажатый во время отсчёта перед автозапуском) — иначе он "проглатывает" первый
# же вопрос (порт/bore) мгновенно, без реального выбора.
while read -r -t 0.05 -n 1000 _discard 2>/dev/null; do :; done

# ---------- Цвета и стрелочные меню (тот же стиль, что у установщика) ----------
# cargo кладёт bore в ~/.cargo/bin — эта папка не всегда попадает в PATH
# новой сессии Termux, из-за чего "command -v bore" не находит уже стоящий bore
# и скрипт снова предлагает установку. Явно добавляем путь на всякий случай.
export PATH="\$HOME/.cargo/bin:\$PATH"

PORT_FILE="port.txt"
C_RESET='\033[0m'
C_BOLD='\033[1m'
C_DIM='\033[2m'
C_ACCENT='\033[38;5;114m'
C_CYAN='\033[38;5;110m'

arrow_select() {
  local prompt="\$1"; shift
  local opts=("\$@")
  local sel=0
  local key rest
  while true; do
    clear >&2
    printf "\${C_CYAN}\${C_BOLD}%s\${C_RESET}\n\n" "\$prompt" >&2
    for i in "\${!opts[@]}"; do
      if [ "\$i" -eq "\$sel" ]; then
        printf "  \${C_ACCENT}\${C_BOLD}➤ %s\${C_RESET}\n" "\${opts[\$i]}" >&2
      else
        printf "    \${C_DIM}%s\${C_RESET}\n" "\${opts[\$i]}" >&2
      fi
    done
    printf "\n\${C_DIM}(↑/↓ — выбор, Enter — подтвердить)\${C_RESET}\n" >&2
    IFS= read -rsn1 key
    if [[ "\$key" == \$'\x1b' ]]; then
      IFS= read -rsn2 -t 0.2 rest
      case "\$rest" in
        '[A') sel=\$(( (sel - 1 + \${#opts[@]}) % \${#opts[@]} )) ;;
        '[B') sel=\$(( (sel + 1) % \${#opts[@]} )) ;;
      esac
    elif [[ -z "\$key" ]]; then
      break
    fi
  done
  echo "\$sel"
}

ask_yn() {
  local idx
  idx=\$(arrow_select "\$1" "Да" "Нет")
  [ "\$idx" = "0" ]
}

pick_port() {
  local saved=""
  if [ -f "\$PORT_FILE" ]; then
    saved="\$(tr -d '[:space:]' < "\$PORT_FILE" 2>/dev/null)"
  fi

  # Нет интерактивного терминала — не задаём вопросов, тихо берём сохранённый порт
  # или 4000, и НЕ сохраняем этот выбор в файл (чтобы не "залочить" порт навсегда).
  if [ ! -t 0 ]; then
    echo "\${saved:-4000}"
    return
  fi

  if [ -n "\$saved" ]; then
    local idx
    idx=\$(arrow_select "Уже сохранён порт \$saved. Продолжить с ним?" "Да, использовать \$saved" "Нет, ввести другой порт")
    if [ "\$idx" = "0" ]; then
      echo "\$saved"
      return
    fi
  fi

  # Порты, которые Chrome/Chromium считают "небезопасными" и блокирует намертво
  # (ERR_UNSAFE_PORT) — сюда же попадает популярный 6000 (X11). Если такой выбрали,
  # предупреждаем и просим ввести другой, а не тихо ломаем и заставляем гадать.
  UNSAFE_PORTS=" 1 7 9 11 13 15 17 19 20 21 22 23 25 37 42 43 53 69 77 79 87 95 101 102 103 104 109 110 111 113 115 117 119 123 135 137 139 143 161 179 389 427 465 512 513 514 515 526 530 531 532 540 548 554 556 563 587 601 636 989 990 993 995 1719 1720 1723 2049 3659 4045 5060 5061 6000 6566 6665 6666 6667 6668 6669 6697 10080 "

  while true; do
    clear
    echo "Введи порт (по умолчанию 4000):"
    read -rp "> " new_port
    new_port="\${new_port:-4000}"
    if ! [[ "\$new_port" =~ ^[0-9]+\$ ]] || [ "\$new_port" -lt 1 ] || [ "\$new_port" -gt 65535 ]; then
      echo "[!] Некорректный порт, использую 4000."
      new_port=4000
      break
    fi
    if [[ "\$UNSAFE_PORTS" == *" \$new_port "* ]]; then
      echo "[!] Порт \$new_port браузер блокирует как небезопасный (ERR_UNSAFE_PORT) — сайт на нём не откроется."
      echo "    Введи другой, например 8080, 8000, 3000, 5000."
      continue
    fi
    break
  done
  echo "\$new_port" > "\$PORT_FILE"
  echo "\$new_port"
}

MANAGER_PORT="\$(pick_port)"
export MANAGER_PORT
clear

# Определяем реальный локальный IP устройства (для ссылки, которую можно скопировать
# и вставить в клиент-панель) — пробуем пару способов, т.к. не везде есть одно и то же.
detect_local_ip() {
  local ip
  ip="\$(ip route get 1.1.1.1 2>/dev/null | sed -n 's/.*src \([0-9.]*\).*/\1/p')"
  if [ -z "\$ip" ] && command -v ifconfig >/dev/null 2>&1; then
    ip="\$(ifconfig 2>/dev/null | grep -A1 'wlan0\|eth0' | grep 'inet ' | head -1 | sed -n 's/.*inet \([0-9.]*\).*/\1/p')"
  fi
  echo "\$ip"
}
LOCAL_IP="\$(detect_local_ip)"
LINKS_FILE="\$HOME/bot-links.txt"
: > "\$LINKS_FILE"

if [ "\$INSTALL_MODE" = "server" ]; then
  echo "[i] Сервер для ботов слушает порт: \$MANAGER_PORT (сменить порт — снова запусти ~/start-server-api)"
  echo "[i] Своей веб-панели тут нет. Управляй этим сервером из клиент-панели."

  # ---------- Bore-туннель, чтобы сервер был виден из интернета ----------
  BORE_UP=0
  setup_bore_tunnel() {
    if ! command -v bore >/dev/null 2>&1; then
      if ask_yn "bore не установлен. Установить сейчас? (соберётся через cargo, может занять пару минут)"; then
        command -v pkg >/dev/null 2>&1 && pkg install -y rust >/dev/null 2>&1
        if command -v cargo >/dev/null 2>&1; then
          echo "[i] Собираю bore-cli, подожди..."
          cargo install bore-cli
        else
          echo "[!] cargo не найден — установи вручную: pkg install rust && cargo install bore-cli"
          return
        fi
      else
        return
      fi
    fi
    if ! command -v bore >/dev/null 2>&1; then
      echo "[!] bore всё ещё не найден, пропускаю туннель."
      return
    fi
    echo "[i] Поднимаю bore-туннель для порта \$MANAGER_PORT..."
    rm -f bore-tunnel.log bore-address.txt
    bore local "\$MANAGER_PORT" --to bore.pub > >(tee bore-tunnel.log) 2>&1 &
    echo \$! > bore-tunnel.pid
    echo "[i] Жду подключения bore (вывод самого bore виден ниже)..."
    sleep 4
    bore_addr="\$(grep -o 'bore\.pub:[0-9]*' bore-tunnel.log | head -1)"
    if [ -n "\$bore_addr" ]; then
      echo "\$bore_addr" > bore-address.txt
      echo "Публично (bore): http://\$bore_addr" >> "\$LINKS_FILE"
      BORE_UP=1
    else
      echo "[!] Пока не нашёл публичный адрес автоматически."
      echo "    Смотри вывод bore выше — там должна быть строка вида \"listening at bore.pub:XXXXX\"."
      echo "    Он же сохраняется в файл bore-tunnel.log."
    fi
  }

  # ---------- Ссылка: только IP:порт, localhost в серверном режиме никогда не даём ----------
  if [ -n "\$LOCAL_IP" ]; then
    echo "Локальная сеть: http://\$LOCAL_IP:\$MANAGER_PORT" >> "\$LINKS_FILE"
    # IP есть — bore предлагаем как опцию (доступ и так есть в локальной сети)
    if [ -t 0 ]; then
      if ask_yn "Поднять bore-туннель, чтобы этот сервер был доступен из интернета (не только по локальной сети)?"; then
        setup_bore_tunnel
      fi
    fi
  else
    echo "[!] Не удалось автоматически определить локальный IP этого устройства."
    if [ -t 0 ]; then
      if ask_yn "IP не найден — поднять bore-туннель, чтобы сервер был доступен хоть как-то?"; then
        setup_bore_tunnel
        if [ "\$BORE_UP" != "1" ]; then
          echo "[✗] Bore-туннель не поднялся, а локальный IP не определён — у сервера нет ни одного"
          echo "    рабочего адреса. Останавливаюсь, чтобы не висеть бесполезно."
          exit 1
        fi
      else
        echo "[✗] Без IP и без bore-туннеля сервер недоступен ни из сети, ни снаружи. Останавливаюсь."
        exit 1
      fi
    else
      echo "[✗] Нет интерактивного терминала, IP не найден, bore не поднят — сервер недоступен. Останавливаюсь."
      exit 1
    fi
  fi
else
  echo "[i] Панель слушает порт: \$MANAGER_PORT (сменить порт — снова запусти ~/start-web-panel.sh)"
  echo "На этом устройстве: http://localhost:\$MANAGER_PORT" >> "\$LINKS_FILE"
  if [ -n "\$LOCAL_IP" ]; then
    echo "Из локальной сети: http://\$LOCAL_IP:\$MANAGER_PORT" >> "\$LINKS_FILE"
  fi
fi

# ---------- Итоговая сводка ссылок — печатается ПОСЛЕДНЕЙ, чтобы не потерялась
# в потоке предыдущего вывода (установка bore и т.п.), и сохраняется в файл,
# который можно посмотреть в любой момент: cat ~/bot-links.txt
clear
printf "\${C_CYAN}\${C_BOLD}=============================================\${C_RESET}\n"
printf "\${C_CYAN}\${C_BOLD} Ссылки для подключения\${C_RESET}\n"
printf "\${C_CYAN}\${C_BOLD}=============================================\${C_RESET}\n"
if [ -s "\$LINKS_FILE" ]; then
  while IFS= read -r link_line; do
    printf "\${C_ACCENT}\${C_BOLD}[✓] %s\${C_RESET}\n" "\$link_line"
  done < "\$LINKS_FILE"
else
  echo "[!] Не удалось определить ни одной ссылки автоматически."
  echo "    Посмотри IP сам: ip addr (или Настройки → Wi-Fi → подключение)"
  echo "    и подставь порт \$MANAGER_PORT вручную."
fi
echo
echo "Эти же ссылки сохранены в файл — посмотреть в любой момент:"
echo "   cat ~/bot-links.txt"
echo

echo "[i] Запущено (с автоперезапуском). Ctrl+C — остановить."
echo

# Ждёт, пока порт реально начнёт отвечать (без внешних зависимостей — через
# встроенный в bash /dev/tcp), и только тогда открывает браузер. Раньше браузер
# открывался СРАЗУ, ещё до того как node успевал поднять сервер — отсюда
# ERR_CONNECTION_REFUSED при первом запуске. Работает как отдельная фоновая
# задача, никак не завязанная на сам node manager.js — чтобы не трогать
# его foreground-запуск и не ломать нормальную остановку по Ctrl+C.
if [ "\$INSTALL_MODE" = "client" ]; then
  (
    tries=0
    while [ \$tries -lt 40 ]; do
      if (exec 3<>"/dev/tcp/127.0.0.1/\$MANAGER_PORT") 2>/dev/null; then
        exec 3<&- 3>&- 2>/dev/null
        if command -v termux-open-url >/dev/null 2>&1; then
          termux-open-url "http://localhost:\$MANAGER_PORT"
        fi
        break
      fi
      sleep 0.5
      tries=\$((tries + 1))
    done
  ) &
fi

while true; do
  # Node мог сломаться между запусками (рассинхрон с openssl после pkg upgrade) — чиним на лету
  if command -v node >/dev/null 2>&1 && ! node --version >/dev/null 2>&1; then
    echo "[!] Node.js повреждён, пытаюсь починить перед запуском..."
    pkg install -y -o Dpkg::Options::=--force-confnew openssl >/dev/null 2>&1
    pkg reinstall -y -o Dpkg::Options::=--force-confnew nodejs openssl >/dev/null 2>&1
  fi

  start_ts=\$(date +%s)
  node manager.js
  exit_code=\$?
  end_ts=\$(date +%s)
  echo "[\$(date '+%Y-%m-%d %H:%M:%S')] manager.js завершился (код \$exit_code)" >> "\$RESTART_LOG"

  # код 0 / 130 (Ctrl+C) / 143 (SIGTERM) считаем осознанной остановкой
  if [ "\$exit_code" -eq 0 ] || [ "\$exit_code" -eq 130 ] || [ "\$exit_code" -eq 143 ]; then
    echo "[i] Остановлено вручную."
    break
  fi

  if [ \$((end_ts - start_ts)) -lt 5 ]; then
    fast_restart_count=\$((fast_restart_count + 1))
  else
    fast_restart_count=0
  fi

  if [ "\$fast_restart_count" -ge "\$MAX_FAST_RESTARTS" ]; then
    echo "[✗] manager.js падает подряд \$MAX_FAST_RESTARTS раз почти сразу после старта."
    echo "    Останавливаюсь, чтобы не спамить. Смотри supervisor.log и логи ботов в bots/*/logs."
    break
  fi

  echo "[!] manager.js упал (код \$exit_code), перезапуск через 3 сек..."
  sleep 3
done
INNEREOF
chmod +x "$TARGET/$LAUNCHER_NAME"

cat > "$HOME/$LAUNCHER_NAME" << SHORTCUTEOF
#!/usr/bin/env bash
cd "$TARGET"
exec ./$LAUNCHER_NAME
SHORTCUTEOF
chmod +x "$HOME/$LAUNCHER_NAME"
echo "      готово."
echo

echo "[5/5] Устанавливаем зависимости панели (express)..."
echo "      Вывод npm будет виден ниже, подожди немного..."
(cd "$TARGET" && npm install --ignore-scripts express)
echo "      готово."

INST_DATE="$(date -u +"%Y-%m-%dT%H:%M:%SZ" 2>/dev/null || date)"
FEATURES_JSON="$(echo "$INSTALLER_FEATURES" | sed 's/,/","/g')"
cat > "$TARGET/inst.json" << INSTEOF
{
  "version": "$INSTALLER_VERSION",
  "installedAt": "$INST_DATE",
  "features": ["$FEATURES_JSON"],
  "mode": "$INSTALL_MODE",
  "target": "$TARGET"
}
INSTEOF

echo
echo "============================================="
echo " Готово!"
echo "============================================="
echo "Папка проекта: $TARGET"
if [ "$INSTALL_MODE" = "client" ]; then
  echo "Запуск панели из любого места:"
  echo "   ~/start-web-panel.sh"
  echo "При запуске спросит порт и попробует сама открыть браузер."
else
  echo "Запуск сервера-хоста ботов (без веб-панели) из любого места:"
  echo "   ~/start-server-api"
  echo "При запуске спросит порт и предложит поднять bore-туннель для внешнего доступа."
  echo "Управляй этим сервером с отдельной клиент-панели (добавь его адрес во вкладке «Серверы»)."
fi
echo
echo "Хочешь получать уведомления при падении бота / автоподключении?"
echo "Поставь из Google Play/F-Droid приложение Termux:API, затем в Termux:"
echo "   pkg install termux-api"

else
  echo "============================================="
  echo " Переустановка пропущена"
  echo "============================================="
  echo "Ничего не менялось. Твоя установка осталась как есть в: $TARGET"
  if [ "$INSTALL_MODE" = "client" ]; then
    echo "Запуск панели из любого места:"
    echo "   ~/start-web-panel.sh"
  else
    echo "Запуск сервера из любого места:"
    echo "   ~/start-server-api"
  fi
fi

# ---------- Запуск ----------
# Запускаем В ТЕКУЩЕМ терминале (не в фоне через nohup) — иначе выбор порта
# не может быть интерактивным и всегда падает на 4000 по умолчанию, плюс старый
# фоновый процесс остаётся висеть и занимать порт при попытке перезапуска на другом.
LAUNCHER_PATH="$HOME/$LAUNCHER_NAME"
echo
if [ -f "$LAUNCHER_PATH" ]; then
  if [ -t 0 ]; then
    echo "Запускаю через 2 секунды (Ctrl+C — отменить и запустить позже вручную: $LAUNCHER_PATH)..."
    sleep 2
    while read -r -t 0.05 -n 1000 _discard 2>/dev/null; do :; done
    exec "$LAUNCHER_PATH"
  else
    echo "[i] Нет интерактивного терминала — не запускаю автоматически."
    echo "    Запусти вручную: $LAUNCHER_PATH"
  fi
else
  echo "[!] $LAUNCHER_PATH не найден — что-то пошло не так при установке."
fi
